/**
 * The block / mark / document types' entry: the block id, the doc meta,
 * the JSON document shape, and the doc-attribute's value types. The
 * per-block attrs and the page / sync-embed / divider block interfaces
 * stand in block-attrs; the inline text types (the mark set, the runs)
 * stand in text; the table / canvas / database block types stand in their
 * own files.
 */
import type { Block } from "./block-union";
import type { TextRun } from "./text";

/** Block identifier (nanoid, generated by the change author; never reused). */
type BlockId = string;

type TextAlign = "left" | "center" | "right";

/**
 * A mention reference (the preset user attribute's value form, like the
 * in-text `mention` mark minus its kind): the stable target id. The mark is
 * the identity — the display label is the consumer's resolution (its own
 * catalog / the `renderAttribute`'s stand). The legacy `label` snapshot
 * (pre-id-only stands) stands tolerated and ignored by the writer.
 */
type MentionRef = {
  id: string;
  /** The legacy label snapshot (tolerated over the lenient read).
   * @deprecated The writer stands the id-only ref; the label is the
   *  consumer's resolution over the id. */
  label?: string;
};

/**
 * A custom attribute's declared type (the consumer's type-picker's
 * vocabulary — the `ATTRIBUTE_TYPES` constant). The type is the value's
 * form contract: the typed value stands the declared type + the value over
 * its form.
 */
type AttributeType = "string" | "number" | "boolean" | "list" | "mention";

/**
 * A typed attribute value (the custom attribute's storage form): the
 * declared `type` + the `value` over that type's form. A preset attribute
 * stands its plain value (the type is implicit over its key); a custom
 * attribute stands this wrapper (the type stands over an empty value, too).
 */
type TypedAttributeValue =
  | { type: "string"; value: string }
  | { type: "number"; value: number }
  | { type: "boolean"; value: boolean }
  | { type: "list"; value: string[] }
  | { type: "mention"; value: MentionRef };

/**
 * A document attribute's value (`DocMeta.attributes`): a scalar or a
 * string list, a mention reference, or the typed value (the custom
 * attribute's storage form). Arbitrary nested objects are not supported (an
 * unsupported value is preserved as-is by the lenient reader only).
 */
type DocAttributeValue = string | number | boolean | string[] | MentionRef | TypedAttributeValue;

/** Document metadata. */
interface DocMeta {
  /** Schema version. */
  v: 1;
  /** Document identifier (nanoid). */
  id: string;
  /** Document title (empty string is a valid state). */
  title: string;
  /** The page avatar (a short string / a few emoji; absent or empty = none). */
  avatar?: string;
  /**
   * Document-level attributes (the consumer's own metadata — the markdown
   * frontmatter's stand): a plain `key → value` record; absent or empty =
   * none. The keys are non-empty strings (the doc meta fields and the
   * Object.prototype keys are reserved); the values are `string | number |
   * boolean | string[]`, the mention reference (`{ id }`, id-only; the
   * legacy `label` snapshot is tolerated), or the typed value (`{ type,
   * value }` — the custom attribute's storage form).
   */
  attributes?: Record<string, DocAttributeValue>;
  /**
   * The attribute keys' display order (additive, the custom attribute's
   * drag-reorder's persistence): the order over the `attributes` record's
   * keys (the writer maintains a permutation of the record's keys; the
   * UI's preset rows stand a fixed order of their own and ignore the
   * preset keys' entries). Absent = the record's key order stands (the
   * reader's fallback).
   */
  attributesOrder?: string[];
  /** Creation time, ISO 8601. */
  createdAt: string;
}

/**
 * An opaque block snapshot: a block of an unknown type (a future minor's
 * data) preserved as-is. The reader/renderer stand a placeholder (and the
 * text without the unknown marks); the data is not lost on save (the writer's
 * opaque stand). The strict validator rejects it (the writer's contract — a
 * v1 writer never emits it).
 *
 * The `type` is a plain string (a name outside the v1 registry): a
 * `block.type === "<known>"` check narrows away the other known members but
 * keeps this one (the type is unknown), so a specific known type is accessed
 * through a narrowed cast after the check.
 *
 * The index signature is the cross-minor stand for additive top-level fields
 * (a future minor may add fields beyond `attrs`/`content`/`children`/
 * `geometry`): the read/write opaque paths keep them intact, so a save
 * never drops data the engine does not know.
 */
interface OpaqueBlock {
  /** The unknown block type (a name outside the v1 registry). */
  type: string;
  attrs?: Record<string, unknown>;
  content?: TextRun[];
  children?: BlockId[];
  geometry?: Record<string, number>;
  /** Additive top-level fields of a future minor (preserved as-is). */
  [key: string]: unknown;
}

/** Document in the public JSON format. */
interface DocJSON extends DocMeta {
  /** Flat map: block id -> block. Order lives in `children`. An unknown-type block (a future minor's data) stands as the opaque entry. */
  blocks: Record<BlockId, Block | OpaqueBlock>;
}

/** The flat-page nesting depth of a page block relative to the preceding block of the same sequence (default 0). */
type PageIndent = number;

export type {
  AttributeType,
  BlockId,
  DocAttributeValue,
  DocJSON,
  DocMeta,
  MentionRef,
  OpaqueBlock,
  PageIndent,
  TextAlign,
  TypedAttributeValue,
};

export type {
  CalloutAttrs,
  CalloutBlock,
  CodeAttrs,
  CodeBlock,
  DividerAttrs,
  DividerBlock,
  EmbedAttrs,
  EmbedBlock,
  FileAttrs,
  FileBlock,
  HeadingAttrs,
  HeadingBlock,
  ImageAttrs,
  ImageBlock,
  ListItemAttrs,
  ListItemBlock,
  ParagraphAttrs,
  ParagraphBlock,
  QuoteAttrs,
  QuoteBlock,
  RootBlock,
  SyncEmbedAttrs,
  SyncEmbedBlock,
  SyncEmbedRef,
  TableCellAttrs,
} from "./block-attrs";
export type {
  CanvasRef,
  CanvasTextAttrs,
  CanvasTextBlock,
  ConnectorAttrs,
  ConnectorBlock,
  FrameAttrs,
  FrameBlock,
  Geometry,
  GroupAttrs,
  GroupBlock,
  ShapeAttrs,
  ShapeBlock,
  SurfaceAttrs,
  SurfaceBlock,
  WithGeometry,
} from "./canvas";
export type {
  DatabaseAttrs,
  DatabaseBlock,
  DatabaseCellType,
  DatabaseCellValue,
  DatabaseColumn,
  DatabaseFilterCondition,
  DatabaseFilterPayload,
  DatabaseSavedView,
} from "./database";
